-- Gunita Kopi POS: product images in Supabase Storage (SRS FR-50, SRS 4.3; SDS 2.6 "Private files
-- with access checks", 2.8 "Supabase Storage with authorized access only", 3.5.4 products.image).
--   * Private bucket: no public URLs. Files are read through apps/api (GET /api/products/{id}/image)
--     with the caller's token, so these policies apply to every read.
--   * products.image keeps the object path inside the bucket ("<product_id>/<uuid>.<ext>"),
--     generated by apps/api; existing values (empty or http(s) URLs) are left as they are.
--   * Upload limits are also enforced by the bucket: 2 MB, PNG, JPEG or WebP.
-- Not applied to the live project yet; see docs/database.md "Product images".

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('product-images', 'product-images', false, 2097152,
        array['image/png', 'image/jpeg', 'image/webp'])
on conflict (id) do nothing;

-- Both roles see product images (POS menu, Admin product list); only the Owner manages them.
-- Upsert needs insert + select + update, replacing a file needs delete.
create policy product_images_read on storage.objects for select to authenticated
  using (bucket_id = 'product-images' and public.app_role() is not null);
create policy product_images_owner_insert on storage.objects for insert to authenticated
  with check (bucket_id = 'product-images' and public.app_role() = 'owner_admin');
create policy product_images_owner_update on storage.objects for update to authenticated
  using (bucket_id = 'product-images' and public.app_role() = 'owner_admin')
  with check (bucket_id = 'product-images' and public.app_role() = 'owner_admin');
create policy product_images_owner_delete on storage.objects for delete to authenticated
  using (bucket_id = 'product-images' and public.app_role() = 'owner_admin');
